# Re-parse to get only the actual graph edges (after the example)
full_edges = context.split("Here is the graph to operate on:\nThe graph has the following edges:\n")[1]
full_edges = full_edges.split("\n\nOperation:")[0]

adj = {}
for line in full_edges.strip().split('\n'):
    if ' -> ' in line:
        src, dst = line.split(' -> ')
        if src not in adj:
            adj[src] = []
        adj[src].append(dst)

print("Corrected adjacency list:")
for k, v in sorted(adj.items()):
    print(f"  {k} -> {v}")

print(f"\nStart node c4ca4238a0 has edges to: {adj.get('c4ca4238a0', [])}")

# BFS from c4ca4238a0, tracking depths
from collections import deque

start = 'c4ca4238a0'
visited = {start: 0}
queue = deque([start])
nodes_at_depth = {0: {start}}

while queue:
    node = queue.popleft()
    current_depth = visited[node]

    for neighbor in adj.get(node, []):
        if neighbor not in visited:
            visited[neighbor] = current_depth + 1
            queue.append(neighbor)
            if current_depth + 1 not in nodes_at_depth:
                nodes_at_depth[current_depth + 1] = set()
            nodes_at_depth[current_depth + 1].add(neighbor)

print(f"\nBFS results:")
for d in sorted(nodes_at_depth.keys()):
    print(f"  Depth {d}: {sorted(nodes_at_depth[d])}")
```

